SELECT c.c_customer_id, wp.wp_type, SUM(ws.ws_ext_sales_price) AS total_sales, COUNT(DISTINCT ws.ws_order_number) AS order_cnt FROM web_sales ws JOIN customer c ON ws.ws_bill_customer_sk = c.c_customer_sk JOIN web_page wp ON ws.ws_web_page_sk = wp.wp_web_page_sk WHERE ws.ws_sold_date_sk BETWEEN 2451771 AND 2451483 AND c.c_birth_year = 1951 GROUP BY c.c_customer_id, wp.wp_type HAVING SUM(ws.ws_ext_sales_price) > 181.86
